import type { ControlParameter, FrameworkControlDefinition, FrameworkDefinition, FrameworkDomainInfo } from '../../../types/framework';
import catalogFile from './catalog.generated.json';
import type { GeneratedR3CatalogFile, GeneratedR3Requirement } from './types';
import { parseParameterTags } from '../parameters';
import { summarizeStatement } from '../nist80053Controls';
import { attachDodDefaults } from './odp';

/**
 * NIST SP 800-171 Rev. 3 (Protecting CUI in Nonfederal Systems): its 97 requirements, generated by scripts/generateNist171r3.ts
 * from NIST's OSCAL catalog. Each requirement carries its official statement with the [Assignment: ...] / [Selection: ...] tags
 * where Rev. 3 has organization-defined parameters (ODPs), so the parameter panel works as it does for SP 800-53. Rev. 3 has no
 * baselines and no overlays. The SP 800-171A Rev. 3 objectives are in objectives.ts and the Rev. 2 -> Rev. 3 mapping in r2r3.ts.
 *
 * Rev. 3 ids ("03.01.01") match no CMMC, SP 800-53 or SP 800-171 Rev. 2 id, so findControlDefinition resolves them unambiguously.
 */
const FAMILY_DETAILS: Record<string, Omit<FrameworkDomainInfo, 'code' | 'name' | 'totalControls'>> = {
  '03.01': { description: 'Account management, access enforcement, least privilege, session controls, remote and wireless access, and mobile devices.', iconName: 'ShieldCheck', color: '#0284c7' },
  '03.02': { description: 'Security literacy training and role-based training.', iconName: 'GraduationCap', color: '#6366f1' },
  '03.03': { description: 'Event logging, audit record content, review, reduction, time stamps, and protection of audit information.', iconName: 'FileText', color: '#a855f7' },
  '03.04': { description: 'Baseline configurations, change control, least functionality, and system component inventory.', iconName: 'Settings', color: '#ec4899' },
  '03.05': { description: 'User, service and device identification, authenticator management, and multi-factor authentication.', iconName: 'KeyRound', color: '#8b5cf6' },
  '03.06': { description: 'Incident handling, incident reporting, incident response testing and training, and the incident response plan.', iconName: 'AlertOctagon', color: '#ef4444' },
  '03.07': { description: 'Maintenance tools, nonlocal maintenance, and maintenance personnel.', iconName: 'Wrench', color: '#f97316' },
  '03.08': { description: 'Media storage, access, marking, transport, sanitization, and use.', iconName: 'HardDriveDownload', color: '#eab308' },
  '03.09': { description: 'Personnel screening, and protection of CUI during personnel actions.', iconName: 'Users', color: '#14b8a6' },
  '03.10': { description: 'Physical access authorizations and control, monitoring physical access, and alternate work sites.', iconName: 'Building2', color: '#f59e0b' },
  '03.11': { description: 'Risk assessment, vulnerability monitoring and scanning, and risk response.', iconName: 'TrendingDown', color: '#84cc16' },
  '03.12': { description: 'Control assessments, plans of action and milestones, continuous monitoring, and connections to other systems.', iconName: 'ClipboardCheck', color: '#06b6d4' },
  '03.13': { description: 'Boundary protection, cryptography, session and network communications protection, and denial of service.', iconName: 'Network', color: '#059669' },
  '03.14': { description: 'Flaw remediation, malicious code protection, system monitoring, and security alerts.', iconName: 'CheckCircle2', color: '#3b82f6' },
  '03.15': { description: 'The system security plan, rules of behavior, and the boundary of the system.', iconName: 'BookOpen', color: '#64748b' },
  '03.16': { description: 'Security engineering principles, unsupported system components, and external system services.', iconName: 'ShoppingBag', color: '#0ea5e9' },
  '03.17': { description: 'Supply chain risk management plan, acquisition strategies, and supply chain controls and processes.', iconName: 'Truck', color: '#d97706' },
};

const catalog = catalogFile as unknown as GeneratedR3CatalogFile;

/**
 * The parameters of a requirement, computed once from its statement: parameter "<id>#n" is the nth outermost tag, which is
 * requirements[i].odps[n - 1]. NIST's own sentence for the ODP ("the time period for account inactivity before disabling is
 * defined.") becomes the prompt of an Assignment, which is where ControlParameter says what has to be decided.
 */
function parametersOf(r: GeneratedR3Requirement): ControlParameter[] {
  return parseParameterTags(r.statement, r.id).map((p, i) => {
    const guideline = catalog.odps[r.odps[i]]?.guideline;
    return p.kind === 'ASSIGNMENT' && guideline ? { ...p, prompt: guideline } : p;
  });
}

function toDefinition(r: GeneratedR3Requirement): FrameworkControlDefinition {
  return {
    id: r.id,
    title: r.title,
    statement: r.statement,
    parameters: parametersOf(r),
    framework: 'NIST_800_171_R3',
    domain: r.family,
    domainName: FAMILY_TITLES.get(r.family) ?? r.family,
    authorityReference: `NIST SP 800-171 Rev 3 ${r.id}`,
    plainEnglishSummary: summarizeStatement(r.statement),
    discussion: r.discussion,
    assessmentObjectives: [],
    auditorChecklist: [],
    nonNetworkedApplicable: true,
  };
}

const FAMILY_TITLES = new Map(catalog.families.map((f) => [f.code, f.title]));

/**
 * The control list. A function, so a later step (the DoD ODP values) can wrap it and add defaults to `parameters` without
 * this module knowing about them. Every call builds new objects.
 */
export function buildR3Controls(): FrameworkControlDefinition[] {
  return catalog.requirements.map(toDefinition);
}

export const NIST_171_R3_CONTROLS: FrameworkControlDefinition[] = attachDodDefaults(buildR3Controls());

const familyCounts = new Map<string, number>();
for (const c of NIST_171_R3_CONTROLS) familyCounts.set(c.domain, (familyCounts.get(c.domain) ?? 0) + 1);

/** The seventeen requirement families, with the number of requirements in each. */
export const NIST_171_R3_DOMAINS: Record<string, FrameworkDomainInfo> = Object.fromEntries(
  catalog.families.map((f) => [
    f.code,
    { ...(FAMILY_DETAILS[f.code] ?? { description: f.title, iconName: 'Shield', color: '#64748b' }), code: f.code, name: f.title, totalControls: familyCounts.get(f.code) ?? 0 },
  ])
);

export const NIST_171_R3_DEF: FrameworkDefinition = {
  id: 'NIST_800_171_R3',
  name: 'NIST SP 800-171 Rev. 3 (Protecting CUI)',
  shortName: 'NIST SP 800-171 Rev. 3',
  version: 'Rev 3',
  authority: 'NIST SP 800-171 Rev. 3 / NIST SP 800-171A Rev. 3',
  description: `${NIST_171_R3_CONTROLS.length} security requirements across ${Object.keys(NIST_171_R3_DOMAINS).length} families protecting Controlled Unclassified Information (CUI) in nonfederal systems, with organization-defined parameters. No baselines: every requirement applies.`,
  totalControls: NIST_171_R3_CONTROLS.length,
  supportsNonNetworkedOverlay: false,
  domains: NIST_171_R3_DOMAINS,
};

/** Provenance of the generated data (source URLs and hashes). */
export const NIST_171_R3_SOURCE = catalog.meta;
